// Run a shell command on server .200 via ssh2, mirroring lib/sftp.ts connection.
// Usage: node run200.js '<remote command>'
// Password is decrypted in-memory from DB, never printed.
const fs = require("fs");
const path = require("path");
const { Client } = require("/opt/nxeon/node_modules/ssh2");
const { PrismaClient } = require("/opt/nxeon/node_modules/@prisma/client");
const { scryptSync, createDecipheriv } = require("node:crypto");

// Load .env
for (const line of fs.readFileSync("/opt/nxeon/.env", "utf8").split("\n")) {
  const m = line.match(/^([A-Z_][A-Z0-9_]*)=(.*)$/);
  if (m && !process.env[m[1]]) process.env[m[1]] = m[2];
}

function deriveKey() {
  return scryptSync(process.env.AUTH_SECRET, "nxeon-byok", 32);
}
function decryptSecret(enc) {
  if (!enc) return null;
  try {
    const [ivB64, tagB64, dataB64] = enc.split(":");
    if (!ivB64 || !tagB64 || !dataB64) return null;
    const d = createDecipheriv("aes-256-gcm", deriveKey(), Buffer.from(ivB64, "base64"));
    d.setAuthTag(Buffer.from(tagB64, "base64"));
    return Buffer.concat([d.update(Buffer.from(dataB64, "base64")), d.final()]).toString("utf8");
  } catch { return null; }
}

