(async () => {
  const prisma = new PrismaClient();
  const server = await prisma.server.findUnique({
    where: { id: SERVER_ID },
    select: { id: true, sshPort: true, rootPassword: true, rootPasswordEnc: true, dedicatedIp: { select: { address: true } } },
  });
  await prisma.$disconnect();
  if (!server) { console.error("server not found"); process.exit(3); }
  const password = decryptSecret(server.rootPasswordEnc) ?? server.rootPassword;
  if (!password) { console.error("no password"); process.exit(4); }
  const dedicated = !!server.dedicatedIp;
