  const port = dedicated ? 22 : server.sshPort;

  // Guard: assert target host is the expected .200 IP.
  if (host !== EXPECT_IP) { console.error("REFUSING: resolved host " + host + " != " + EXPECT_IP); process.exit(5); }

  const conn = new Client();
  conn.on("ready", () => {
    // Assert hostname -I contains the expected IP before running the real command.
    const guarded = `if ! hostname -I | grep -qw ${EXPECT_IP}; then echo "GUARD_FAIL: not ${EXPECT_IP}" >&2; exit 9; fi; ${cmd}`;
