      if (err) { console.error(err); conn.end(); process.exit(6); }
      let code = 0;
      stream.on("close", (c) => { code = c || 0; conn.end(); process.exit(code); });
      stream.on("data", (d) => process.stdout.write(d));
      stream.stderr.on("data", (d) => process.stderr.write(d));
    });
  });
  conn.on("error", (e) => { console.error("SSH error: " + e.message); process.exit(7); });
  conn.connect({ host, port, username: "root", password, readyTimeout: 15000 });
})();

